<script setup>
import {useTableLayout} from '../../shared/composables/tableLayout.js'
const {pinTableActions}=useTableLayout()



import {ref, watch,onBeforeUnmount} from 'vue'
import {deliveryStateLabel,deliveryHash} from '../../deploy/deliveryFlow.js'
import SQLPlanPreview from '../../deploy/components/SQLPlanPreview.vue'
import {api, stamp,openWorkspace} from '../api.js'
const props=defineProps({items:Array,loading:Boolean,error:String,more:Boolean,workItemId:[Number,String]})
const emit=defineEmits(['retry','more'])
const opened=ref(new Set()),details=ref({}),pending=ref({}),errors=ref({})
let generation=0
watch(()=>props.workItemId,()=>{generation++;opened.value=new Set();details.value={};pending.value={};errors.value={}})
const record=r=>details.value[r.id]||r
async function read(r,force=false){if(!r)return;const current=generation,itemId=props.workItemId;if((!force&&(r.loaded||details.value[r.id]))||pending.value[r.id])return;pending.value={...pending.value,[r.id]:true};try{const data=await api('research/work-items/'+itemId+'/delivery-records/'+r.id);if(current!==generation||itemId!==props.workItemId)return;if(data.loaded!==true||data.id!==r.id)throw Error('快照响应无效');details.value={...details.value,[r.id]:data};errors.value={...errors.value,[r.id]:''}}catch(e){if(current!==generation)return;errors.value={...errors.value,[r.id]:e.message}}finally{if(current===generation)pending.value={...pending.value,[r.id]:false}}}
watch(()=>[props.workItemId,props.items?.[0]?.id],([,id])=>{if(id&&opened.value.size===0){opened.value=new Set([id]);read(props.items[0])}},{immediate:true})
function updateOpened(keys){opened.value=new Set(keys);for(const id of keys){const row=props.items.find(r=>String(r.id)===String(id));if(row)read(row)}}
const statuses={blocked:'需要处理',success:'已完成',failed:'失败',pending:'待处理',pending_approval:'待审批',approved:'待执行',waiting_confirmation:'待确认',running:'执行中',rejected:'已驳回',canceled:'已取消',skipped:'已跳过'}
onBeforeUnmount(()=>generation++)
watch(()=>props.items,()=>{for(const id of opened.value){const r=props.items?.find(x=>String(x.id)===String(id));if(r)read(r,true)}},{deep:true})
const kinds={code:'代码与应用',artifact:'应用制品',mysql:'SQL 变更',nacos:'Nacos 配置',redis:'Redis 命令',manual:'自定义记录','data-sync':'数据同步'}
const body=c=>c.sql?.content||c.redis?.commands||c.reference||c.summary||'无补充内容'

import {ref as _viewRef} from 'vue'
const _view1=_viewRef([])


import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Button,Empty,EmptyDescription,EmptyHeader,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../../shared/shadcn-ui.js'
</script>
<template><section aria-label="交付记录" class="work-delivery-records"><p v-if="error" role="alert" class="r-error">交付记录读取失败：{{error}} <Button @click="emit('retry')" variant="outline" size="default" type="button" :disabled="(loading)">重试读取交付记录</Button></p><p v-if="loading" role="status" class="r-muted">正在读取交付记录…</p><Accordion class="delivery-records-panels" type="multiple" :model-value="([...opened]||[]).map(String)" @update:model-value="updateOpened($event)"><AccordionItem v-for="r in items" :value="String(r.id)"><AccordionTrigger><span>{{r.preparation?'交付前置流程':'交付单'}} #{{r.id}} · {{r.environment||'未指定环境'}}</span> <b :class="{failed:r.status==='failed'}">{{deliveryStateLabel(r)}}</b> <small>{{r.owner}} · {{stamp(r.created_at)}}</small></AccordionTrigger><AccordionContent force-mount v-show="!(!([...opened]||[]).map(String).includes(String(r.id)))"><div class="record-content"><div class="mb-3 flex items-start justify-between gap-4"><div><p>{{r.stage}} · {{r.next_action}}</p><p v-if="r.blocked_reason" class="text-destructive">{{r.blocked_reason}}</p></div><Button variant="outline" size="sm" @click="openWorkspace('deploy',deliveryHash(r))">进入交付工作台</Button></div><p v-if="pending[r.id]" role="status">正在读取交付内容快照…</p><p v-if="errors[r.id]" role="alert">快照读取失败：{{errors[r.id]}} <Button @click="read(r)" variant="outline" size="default" type="button">重试读取快照</Button></p><template v-if="record(r).loaded"><p v-if="r.reason" class="r-muted">{{r.reason}}</p><h4>本次交付内容快照</h4><p class="r-muted">展示该次提交的内容，后续编辑不会改变本记录。</p><SQLPlanPreview :plans="record(r).sql_plans"/><div v-for="c in record(r).changes?.filter(c=>!c.sql||!record(r).sql_plans?.length)" :key="c.id" class="snapshot-change"><b>{{kinds[c.kind]||c.kind}} · {{c.title||'#'+c.id}}<span v-if="c.service"> · {{c.service}}</span></b><template v-if="c.nacos"><p>{{c.nacos.resource_alias}} · {{c.nacos.data_id||'环境绑定 Data ID'}} · {{c.nacos.group}}</p><div class="console-table min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:536}).y?({x:536}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:536}).x||({x:536}).minWidth||536)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(180)+'px'}">配置项</TableHead><TableHead :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-background':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-background':''" :style="{width:(176)+'px'}">操作</TableHead><TableHead :style="{width:(180)+'px'}">提交值</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (((c.nacos.entries)||[]).map((e,i)=>({...e,__rowKey:i}))||[])" :key="typeof (&quot;__rowKey&quot;)==='function'?(&quot;__rowKey&quot;)(record):record[&quot;__rowKey&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:e,rowIndex:i} in [{record,rowIndex}]"><div>{{e.key}}</div></template></div></TableCell><TableCell class="align-top" :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-background':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-background':''"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record:e,rowIndex:i} in [{record,rowIndex}]"><div>{{e.action==='delete'?'删除':'设置'}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record:e,rowIndex:i} in [{record,rowIndex}]"><div><pre>{{e.value}}</pre></div></template></div></TableCell></TableRow></template><TableRow v-if="!(((c.nacos.entries)||[]).map((e,i)=>({...e,__rowKey:i}))||[]).length"><TableCell :colspan="3"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></template><template v-else><small v-if="c.sql?.environment_overrides?.length">默认 SQL（本记录未包含执行预检快照）</small><pre>{{body(c)}}</pre><Accordion v-if="c.sql?.environment_overrides?.length" class="platform-collapse" type="multiple" :model-value="(_view1||[]).map(String)" @update:model-value="_view1=$event"><AccordionItem :value="String(&quot;panel&quot;)"><AccordionTrigger>本次保存的 SQL 环境例外</AccordionTrigger><AccordionContent force-mount v-show="!(!(_view1||[]).map(String).includes(String(&quot;panel&quot;)))"><div v-for="e in c.sql.environment_overrides" :key="e.environment"><b>{{e.environment}} · {{e.skip?'无需执行':'专用 SQL'}}</b><p>{{e.reason}}</p><pre v-if="!e.skip">{{e.content}}</pre></div></AccordionContent></AccordionItem></Accordion></template><p v-if="c.rollback_plan" class="r-muted">回退说明：{{c.rollback_plan}}</p></div><p v-if="!record(r).changes?.length&&!record(r).artifacts?.length" class="r-muted">该历史记录未保存内容快照。</p><div v-for="a in record(r).artifacts" :key="a.service" class="snapshot-change"><b>{{a.service}} · {{a.version}}</b><code>{{a.digest}}</code></div><h4 v-if="record(r).steps?.length">执行结果</h4><ol class="step-results"><li v-for="(s,i) in record(r).steps" :key="s.node_id||i"><b>{{s.name}}</b> · <span :class="{failed:s.status==='failed'}">{{statuses[s.status]||s.status}}</span><small v-if="s.service"> · {{s.service}}</small><Accordion v-if="s.detail&&['code-prepare','code-verify'].includes(s.kind)" type="single" collapsible><AccordionItem value="task"><AccordionTrigger>代码任务标识</AccordionTrigger><AccordionContent><pre>{{s.detail}}</pre></AccordionContent></AccordionItem></Accordion><pre v-else-if="s.detail">{{s.detail}}</pre></li></ol></template></div></AccordionContent></AccordionItem></Accordion><Button v-if="more" @click="emit('more')" class="load-more" variant="outline" size="default" type="button" :disabled="(loading)">加载更早的交付记录</Button></section></template>
<style scoped>.delivery-record{border:1px solid var(--border);border-radius:var(--radius);background:var(--panel);overflow:hidden;margin-bottom:10px}.record-heading{display:flex;align-items:center;gap:12px;flex-wrap:wrap;width:100%;padding:12px 16px;border:0;background:var(--panel2);color:var(--text);text-align:left;cursor:pointer;font-size:.875rem}.record-heading small{margin-left:auto;color:var(--muted-foreground)}.record-content{padding:12px 16px;min-width:0}.record-content h4{margin:12px 0 8px;font-size:1rem}.record-content p{font-size:.75rem}.snapshot-change{padding:12px 0;border-bottom:1px solid var(--border);font-size:.875rem;min-width:0}.snapshot-change:last-child{border-bottom:0}.record-content pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:280px;overflow:auto;background:var(--panel2);padding:10px;border:1px solid var(--border);border-radius:var(--radius);font:.75rem/1.7 var(--mono)}.record-content code{display:block;font-size:.75rem;overflow-wrap:anywhere;margin-top:8px}.step-results{padding-left:20px;font-size:.75rem}.step-results li{margin:8px 0}.failed{color:var(--destructive)}</style>
